// ==========================================
// PARTIE 1 : PARCOURS CLIENT (ACHAT)
// ==========================================
// 1. Accès à l'application
cy.visit('test_page.html');
cy.contains('Connexion').should('be.visible');
cy.wait(SLOW_DOWN);
// 2. Connexion Client
cy.get('#email').clear().type('client@baazarnet.com');
cy.wait(500);
cy.get('#password').clear().type('Password123!');
cy.wait(500);
cy.get('#loginBtn').click();
// Vérification redirection
cy.contains('Nos Produits').should('be.visible');
cy.contains('Bonjour, Client').should('be.visible');
cy.wait(SLOW_DOWN);
// 3. Navigation et Ajout au panier
// Ajout iPhone
cy.contains('iPhone 15 Pro').parent().find('button').click();
cy.contains('iPhone 15 Pro ajouté au panier').should('be.visible');
cy.wait(1000);
// Ajout Casque
cy.contains('Casque Sony').parent().find('button').click();
cy.contains('Casque Sony ajouté au panier').should('be.visible');
cy.wait(1000);
// 4. Consultation du Panier
cy.contains('Panier (2)').click();
cy.contains('Mon Panier').should('be.visible');
cy.contains('iPhone 15 Pro').should('be.visible');
cy.contains('Casque Sony').should('be.visible');
cy.get('#cart-total').should('contain', '1348'); // 999 + 349
cy.wait(SLOW_DOWN);
// 5. Validation de la commande (Checkout)
cy.get('#checkoutBtn').click();
cy.contains('Commande Validée !').should('be.visible');
cy.contains('#ORD-2025-889').should('be.visible');
cy.wait(SLOW_DOWN);
// 6. Retour Accueil et Déconnexion
cy.contains('Retour à l\'accueil').click();
cy.wait(500);
cy.contains('Déconnexion').click();
cy.contains('Connexion').should('be.visible');
cy.wait(SLOW_DOWN);
// ==========================================
// PARTIE 2 : PARCOURS ADMIN (MODERATION)
// ==========================================
// 7. Connexion Admin
cy.get('#email').clear().type('admin@baazarnet.com');
cy.wait(500);
cy.get('#password').clear().type('AdminPass123!');
cy.wait(500);
cy.get('#loginBtn').click();
// Vérification Dashboard
cy.contains('Tableau de Bord Administrateur').should('be.visible');
cy.contains('45,300 €').should('be.visible'); // Stats
cy.wait(SLOW_DOWN);
// 8. Action de Modération (Bannir un utilisateur)
cy.contains('Jean Dupont').parent().find('button').click();
// Vérification
cy.contains('Utilisateur banni avec succès').should('be.visible');
cy.contains('Jean Dupont').parent().contains('Banni').should('have.class', 'badge-banned');
cy.wait(SLOW_DOWN);
// 9. Déconnexion Finale
cy.contains('Déconnexion').click();
cy.contains('Connexion').should('be.visible');
cy.wait(SLOW_DOWN);
